import React, { useEffect, useRef, useState, useCallback } from "react";
import Avatar from "./Avatar";
import { useAuth } from "../context/AuthContext";
import { getRoomName, fmtTime, fmtDate, fmtLastSeen } from "../utils/helpers";
import { getChatHistory, getUserStatus } from "../services/api";
import { wsService } from "../services/websocket";

const EMOJI_LIST = ["👍", "❤️", "😂", "😮", "😢", "🔥"];
const TYPING_TIMEOUT = 2500; // ms of silence before sending typing=false

export default function ChatWindow({ room, messages, onNewMessage, wsConnected }) {
  const { username } = useAuth();
  const [text, setText]         = useState("");
  const [loading, setLoading]   = useState(false);
  const [fetched, setFetched]   = useState(false);

  // Feature: typing indicator
  const [typingUsers, setTypingUsers] = useState([]); // usernames currently typing
  const typingTimerRef = useRef(null);
  const isTypingRef    = useRef(false);

  // Feature: last seen
  const [peerStatus, setPeerStatus] = useState(null); // { status, lastSeen }

  const bottomRef = useRef(null);
  const inputRef  = useRef(null);
  const isGroup   = room?.isGroup || room?.group;
  const roomName  = room ? getRoomName(room, username) : "";

  // Fetch history on room change
  useEffect(() => {
    if (!room) return;
    setFetched(false);
    setLoading(true);
    setTypingUsers([]);
    getChatHistory(room.id)
      .then(({ data }) => { onNewMessage(room.id, data, true); setFetched(true); })
      .catch(() => setFetched(true))
      .finally(() => setLoading(false));
  }, [room?.id]);

  // Subscribe messages + typing on room/ws change
  useEffect(() => {
    if (!room) return;
    wsService.subscribeRoom(room.id, (msg) => onNewMessage(room.id, [msg], false));
    wsService.subscribeTyping(room.id, (event) => {
      if (event.username === username) return; // ignore own typing
      setTypingUsers((prev) => {
        if (event.typing) {
          return prev.includes(event.username) ? prev : [...prev, event.username];
        } else {
          return prev.filter((u) => u !== event.username);
        }
      });
      // Auto-clear after 4s in case stop event is lost
      setTimeout(() => {
        setTypingUsers((prev) => prev.filter((u) => u !== event.username));
      }, 4000);
    });
  }, [room?.id, wsConnected]);

  // Feature: fetch peer's status + lastSeen for 1-1 chats
  useEffect(() => {
    if (!room || isGroup) return;
    const peer = (room.participantIds || []).find((u) => u !== username);
    if (!peer) return;
    setPeerStatus(null);
    getUserStatus(peer)
      .then(({ data }) => setPeerStatus(data))
      .catch(() => {});

    // Refresh every 30s while this chat is open
    const interval = setInterval(() => {
      getUserStatus(peer).then(({ data }) => setPeerStatus(data)).catch(() => {});
    }, 30000);
    return () => clearInterval(interval);
  }, [room?.id, isGroup]);

  // Scroll to bottom on new messages
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages?.length]);

  // ── Typing indicator logic ──────────────────────────────────────────────────
  const handleTextChange = (e) => {
    setText(e.target.value);
    e.target.style.height = "auto";
    e.target.style.height = Math.min(e.target.scrollHeight, 128) + "px";

    if (!wsService.connected || !room) return;

    if (!isTypingRef.current) {
      isTypingRef.current = true;
      wsService.sendTyping(room.id, username, true);
    }
    // Reset the stop-typing timer
    clearTimeout(typingTimerRef.current);
    typingTimerRef.current = setTimeout(() => {
      isTypingRef.current = false;
      wsService.sendTyping(room.id, username, false);
    }, TYPING_TIMEOUT);
  };

  // Stop typing on send / blur
  const stopTyping = () => {
    clearTimeout(typingTimerRef.current);
    if (isTypingRef.current && room) {
      isTypingRef.current = false;
      wsService.sendTyping(room.id, username, false);
    }
  };

  const send = useCallback(() => {
    const content = text.trim();
    if (!content || !room) return;
    if (!wsService.connected) return;
    stopTyping();
    wsService.sendMessage(room.id, content, username, username);
    setText("");
    if (inputRef.current) {
      inputRef.current.style.height = "auto";
      inputRef.current.focus();
    }
  }, [text, room, username]);

  const handleKey = (e) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); }
  };

  if (!room) return <EmptyState />;

  const grouped = groupMessagesByDate(messages || []);

  // Build header sub-text: last seen for 1-1, member count for groups
  const headerSub = isGroup
    ? `${(room.participantIds || []).length} members`
    : peerStatus
      ? fmtLastSeen(peerStatus.status, peerStatus.lastSeen)
      : "Loading...";

  const isOnline = !isGroup && peerStatus?.status === "ONLINE";

  return (
    <div className="flex flex-col h-full bg-crisp-bg">

      {/* ── Header ─────────────────────────────────────────────────────────── */}
      <div className="flex items-center gap-3 px-5 py-4 bg-crisp-surface border-b border-crisp-border flex-shrink-0">
        <div className="relative flex-shrink-0">
          <Avatar name={roomName} size="md" square={isGroup} />
          {/* Feature: online dot on peer avatar in 1-1 chat */}
          {isOnline && (
            <span className="absolute bottom-0 right-0 w-3 h-3 bg-crisp-green rounded-full
              border-2 border-crisp-surface" />
          )}
        </div>
        <div className="flex-1 min-w-0">
          <div className="font-display font-bold text-base text-crisp-text truncate">{roomName}</div>
          {/* Feature: last seen / online status */}
          <div className={`text-xs font-mono mt-0.5 transition-colors
            ${isOnline ? "text-crisp-green" : "text-crisp-muted"}`}>
            {headerSub}
          </div>
        </div>
        <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg border text-xs font-mono
          ${wsConnected ? "bg-crisp-card border-crisp-border text-crisp-muted"
                        : "bg-red-500/10 border-red-500/20 text-red-400"}`}>
          <span className={`w-1.5 h-1.5 rounded-full
            ${wsConnected ? "bg-crisp-green" : "bg-red-400 animate-pulse2"}`} />
          {wsConnected ? "Live" : "Reconnecting…"}
        </div>
      </div>

      {/* ── Messages ───────────────────────────────────────────────────────── */}
      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-1">
        {loading && (
          <div className="flex justify-center py-8">
            <div className="flex gap-1">
              {[0,1,2].map(i=>(
                <div key={i} className="w-2 h-2 rounded-full bg-crisp-border2 animate-pulse2"
                  style={{animationDelay:`${i*0.15}s`}} />
              ))}
            </div>
          </div>
        )}

        {!loading && fetched && (!messages || messages.length === 0) && (
          <div className="flex flex-col items-center justify-center h-full gap-3 py-16">
            <div className="text-3xl opacity-30">💬</div>
            <div className="text-crisp-muted text-sm font-body">No messages yet. Say hello!</div>
          </div>
        )}

        {grouped.map(({ date, msgs }) => (
          <div key={date}>
            <div className="flex items-center gap-3 my-4">
              <div className="flex-1 h-px bg-crisp-border" />
              <span className="text-xs text-crisp-muted font-mono px-3 py-1 bg-crisp-card
                border border-crisp-border rounded-full">{date}</span>
              <div className="flex-1 h-px bg-crisp-border" />
            </div>
            {msgs.map((msg, i) => (
              <MessageBubble
                key={msg.id || `${msg.roomId}-${i}-${msg.timestamp}`}
                msg={msg}
                isOwn={msg.senderId === username}
                showSender={isGroup && msg.senderId !== username}
                prevMsg={i > 0 ? msgs[i - 1] : null}
                currentUser={username}
                roomId={room.id}
              />
            ))}
          </div>
        ))}

        {/* Feature: typing indicator */}
        {typingUsers.length > 0 && (
          <TypingIndicator users={typingUsers} />
        )}

        <div ref={bottomRef} />
      </div>

      {/* ── Input ──────────────────────────────────────────────────────────── */}
      <div className="px-4 py-4 bg-crisp-surface border-t border-crisp-border flex-shrink-0">
        <div className="flex items-end gap-3 bg-crisp-card border border-crisp-border2 rounded-2xl
          px-4 py-3 focus-within:border-crisp-accent/50 transition-all duration-200">
          <textarea
            ref={inputRef}
            className="flex-1 bg-transparent text-crisp-text text-sm font-body outline-none
              resize-none placeholder:text-crisp-muted leading-relaxed max-h-32"
            placeholder={`Message ${roomName}…`}
            rows={1}
            value={text}
            onChange={handleTextChange}
            onKeyDown={handleKey}
            onBlur={stopTyping}
          />
          <button onClick={send} disabled={!text.trim() || !wsConnected}
            className="w-9 h-9 bg-crisp-accent hover:bg-crisp-accent2 disabled:opacity-30
              disabled:cursor-not-allowed rounded-xl flex items-center justify-center flex-shrink-0
              transition-all duration-200 active:scale-95 shadow-md shadow-crisp-accent/20">
            <SendIcon />
          </button>
        </div>
        <div className="text-center mt-2 text-[10px] text-crisp-muted font-mono">
          Enter to send · Shift+Enter for new line
        </div>
      </div>
    </div>
  );
}

// ── Feature: Typing Indicator ─────────────────────────────────────────────────
function TypingIndicator({ users }) {
  const label = users.length === 1
    ? `${users[0]} is typing`
    : `${users.slice(0, 2).join(", ")} are typing`;

  return (
    <div className="flex items-center gap-2.5 mt-2 animate-fadeIn px-1">
      <div className="flex gap-0.5 items-center px-3 py-2 bg-crisp-card border border-crisp-border
        rounded-2xl rounded-bl-md">
        {[0,1,2].map(i => (
          <span key={i} className="w-1.5 h-1.5 rounded-full bg-crisp-muted animate-pulse2"
            style={{ animationDelay: `${i * 0.2}s` }} />
        ))}
      </div>
      <span className="text-xs text-crisp-muted font-mono italic">{label}…</span>
    </div>
  );
}

// ── Feature: Message Bubble with Reactions ────────────────────────────────────
function MessageBubble({ msg, isOwn, showSender, prevMsg, currentUser, roomId }) {
  const sameAuthor  = prevMsg?.senderId === msg.senderId;
  const gap         = sameAuthor ? "mt-1" : "mt-3";
  const [showPicker, setShowPicker] = useState(false);
  const pickerRef = useRef(null);

  // Close picker on outside click
  useEffect(() => {
    if (!showPicker) return;
    const handler = (e) => {
      if (pickerRef.current && !pickerRef.current.contains(e.target)) setShowPicker(false);
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [showPicker]);

  const handleReact = (emoji) => {
    wsService.sendReaction(msg.id, roomId, emoji);
    setShowPicker(false);
  };

  const reactions = msg.reactions || {};
  const hasReactions = Object.keys(reactions).length > 0;

  return (
    <div className={`flex items-end gap-2.5 ${isOwn ? "flex-row-reverse" : ""} ${gap} group`}>
      <div className="w-8 flex-shrink-0">
        {!isOwn && !sameAuthor && <Avatar name={msg.senderName || msg.senderId} size="sm" />}
      </div>

      <div className={`flex flex-col max-w-[70%] ${isOwn ? "items-end" : "items-start"}`}>
        {showSender && !sameAuthor && (
          <span className="text-[11px] text-crisp-muted font-display font-semibold mb-1 ml-1">
            {msg.senderName || msg.senderId}
          </span>
        )}

        {/* Bubble + reaction button */}
        <div className={`relative flex items-end gap-1 ${isOwn ? "flex-row-reverse" : ""}`}>
          <div className={`animate-msgIn ${isOwn ? "bubble-own" : "bubble-them"}`}>
            {msg.content}
          </div>

          {/* Reaction trigger button — visible on hover */}
          {msg.id && (
            <div className="relative" ref={pickerRef}>
              <button
                onClick={() => setShowPicker((p) => !p)}
                className="opacity-0 group-hover:opacity-100 transition-opacity w-6 h-6 rounded-full
                  bg-crisp-card border border-crisp-border flex items-center justify-center
                  text-[11px] hover:bg-crisp-hover mb-1 flex-shrink-0"
                title="React">
                😊
              </button>

              {/* Emoji picker popup */}
              {showPicker && (
                <div className={`absolute bottom-8 z-20 flex gap-1 p-2 bg-crisp-surface border
                  border-crisp-border rounded-2xl shadow-xl animate-slideUp
                  ${isOwn ? "right-0" : "left-0"}`}>
                  {EMOJI_LIST.map((emoji) => {
                    const reacted = reactions[emoji]?.includes(currentUser);
                    return (
                      <button
                        key={emoji}
                        onClick={() => handleReact(emoji)}
                        className={`w-8 h-8 rounded-xl flex items-center justify-center text-base
                          transition-all hover:scale-125 active:scale-95
                          ${reacted ? "bg-crisp-accent/20 ring-1 ring-crisp-accent/40" : "hover:bg-crisp-hover"}`}>
                        {emoji}
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Feature: Reaction pills below the bubble */}
        {hasReactions && (
          <div className={`flex flex-wrap gap-1 mt-1 ${isOwn ? "justify-end" : "justify-start"}`}>
            {Object.entries(reactions).map(([emoji, users]) => {
              if (!users || users.length === 0) return null;
              const iMine = users.includes(currentUser);
              return (
                <button
                  key={emoji}
                  onClick={() => wsService.sendReaction(msg.id, roomId, emoji)}
                  className={`flex items-center gap-1 px-2 py-0.5 rounded-full text-xs
                    border transition-all hover:scale-105 active:scale-95 font-mono
                    ${iMine
                      ? "bg-crisp-accent/20 border-crisp-accent/40 text-crisp-accent2"
                      : "bg-crisp-card border-crisp-border text-crisp-muted hover:bg-crisp-hover"}`}>
                  <span>{emoji}</span>
                  <span>{users.length}</span>
                </button>
              );
            })}
          </div>
        )}

        <span className="text-[10px] text-crisp-muted font-mono mt-1 mx-1">
          {fmtTime(msg.timestamp)}
        </span>
      </div>
    </div>
  );
}

function EmptyState() {
  return (
    <div className="flex-1 flex flex-col items-center justify-center gap-4 bg-crisp-bg text-crisp-muted">
      <div className="w-20 h-20 rounded-2xl bg-crisp-surface border border-crisp-border flex items-center justify-center">
        <svg className="w-9 h-9 opacity-40" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
          <path d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/>
        </svg>
      </div>
      <div className="text-center">
        <div className="font-display font-semibold text-crisp-sub text-base mb-1">No chat selected</div>
        <div className="font-body text-sm">Pick a conversation or start a new one</div>
      </div>
    </div>
  );
}

function groupMessagesByDate(messages) {
  const map = {};
  messages.forEach((msg) => {
    const key = fmtDate(msg.timestamp) || "Today";
    if (!map[key]) map[key] = [];
    map[key].push(msg);
  });
  return Object.entries(map).map(([date, msgs]) => ({ date, msgs }));
}

const SendIcon = () => (
  <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
    <line x1="22" y1="2" x2="11" y2="13"/>
    <polygon points="22 2 15 22 11 13 2 9 22 2"/>
  </svg>
);
